import{_ as o,o as s,c as t,a5 as a}from"./chunks/framework.CslsFoWx.js";const i="/VendoraSystem-docs/captures/2026-10-29-boutons-rapides-web/01-grille-accueil.png",r="/VendoraSystem-docs/captures/2026-10-29-boutons-rapides-web/02-edition-bouton.png",n="/VendoraSystem-docs/captures/2026-10-29-boutons-rapides-web/03-ajout-bouton-page-viennoiseries.png",u="/VendoraSystem-docs/captures/2026-10-29-boutons-rapides-web/04-modifications-non-publiees.png",v=JSON.parse('{"title":"Captures : éditeur des boutons rapides, back-office Angular (2026-10-29)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-10-29-boutons-rapides-web.md","filePath":"generated/preuves/2026-10-29-boutons-rapides-web.md","lastUpdated":null}'),d={name:"preuves/2026-10-29-boutons-rapides-web.md"};function c(p,e,l,g,b,m){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="captures-editeur-des-boutons-rapides-back-office-angular-2026-10-29" tabindex="-1">Captures : éditeur des boutons rapides, back-office Angular (2026-10-29) <a class="header-anchor" href="#captures-editeur-des-boutons-rapides-back-office-angular-2026-10-29" aria-label="Permalink to &quot;Captures : éditeur des boutons rapides, back-office Angular (2026-10-29)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-10-29-boutons-rapides-web</code> · 4 image(s) · 0 trace(s)</p><div><p>Lot : boutons rapides (spec 13 phase 1, RG-THEME-08/09), écran <code>/sales-layouts</code> (« Écran de vente » dans le menu). Éditeur <strong>minimal</strong> : grille fidèle aux spans, ajout d&#39;un bouton par case vide, édition ou suppression par clic, pages ajoutables. Pas de glisser-déposer : l&#39;éditeur visuel complet relève de la phase 4.</p><p>Environnement RÉEL : API Spring Boot <code>:8080</code> (migration V6 <code>sales_layouts</code> appliquée), <code>ng serve</code> <code>:4200</code>, compte <code>omar@epicerie.tn</code>, magasin « Épicerie Omar Centre » (profil GROCERY, TND). Chrome headless (puppeteer-core), viewport 1440×900 @2x.</p><p>Données publiées via l&#39;API avant les captures : catégories « Boissons » et « Viennoiseries », produits « Café express » (1,500), « Thé à la menthe » (1,200) et « Croissant » (0,800). Layout « Écran de vente » créé par <code>POST /stores/{id}/sales-layouts</code> (preset GROCERY), puis remplacé par <code>PUT /sales-layouts/{id}</code> → <strong>version 2</strong> : page « Accueil » 4×3 et page « Viennoiseries » 3×2. C&#39;est le même layout que les caisses Android et iOS reçoivent au pull (<code>SalesLayoutUpdated</code>).</p><table tabindex="0"><thead><tr><th>Fichier</th><th>Contenu</th></tr></thead><tbody><tr><td><code>01-grille-accueil.png</code></td><td>Page « Accueil » 4×3 : « Eau 1,5L » <strong>2×2</strong> vert <code>#1B7A43</code>, « Café express » 1×1 <code>#8D5524</code> (texte blanc, choisi par luminance), « Thé à la menthe » 1×1 (couleur du thème), « Croissant » <strong>2×1</strong> jaune <code>#F2B705</code> (texte sombre), bouton <strong>catégorie</strong> « Boissons » 2×1, bouton <strong>page</strong> « Viennoiseries → » 2×1. Les prix (DT, 3 décimales) sont résolus depuis le catalogue. « Version 2 », bouton « Publier » inactif (rien à publier).</td></tr><tr><td><code>02-edition-bouton.png</code></td><td>Clic sur « Eau 1,5L » : bouton surligné, panneau « Modifier le bouton » pré-rempli (type Produit, cible, taille 2×2, couleur <code>#1B7A43</code>) avec Appliquer, Supprimer et Annuler.</td></tr><tr><td><code>03-ajout-bouton-page-viennoiseries.png</code></td><td>Onglet « Viennoiseries » (grille 3×2, « Croissant » 2×2) : clic sur une case vide (<code>+</code>), panneau « Nouveau bouton », cible « Café express ».</td></tr><tr><td><code>04-modifications-non-publiees.png</code></td><td>Après « Ajouter » : « Café express » placé en (0, 2), une case vide restante, « Version 2 — modifications non publiées », bouton « Publier » actif. <strong>Non publié volontairement</strong> : le layout v2 sert aux captures des caisses prises en parallèle.</td></tr></tbody></table><p>Couvert par les tests (<code>layout-editor.spec.ts</code>, 5 tests) plutôt que par des captures :</p><ul><li><strong>publication</strong> : PUT du document complet avec la version lue, puis rechargement (« Publié (version N) ») ;</li><li><strong>409</strong> (modifié ailleurs) : message et rechargement de la version serveur, sans merge (spec 13 §9) ;</li><li><strong>bouton orphelin</strong> (produit désactivé ou supprimé) : surligné en rouge, « masqué en caisse » (RG-THEME-09) ;</li><li><strong>débordement ou chevauchement</strong> refusé dans le panneau ;</li><li><strong>magasin sans layout</strong> : « Créer depuis le preset du magasin ».</li></ul></div><h2 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h2><div class="proof-grid"><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-boutons-rapides-web/01-grille-accueil.png" target="_blank"><img src="'+i+'" alt="01-grille-accueil.png" loading="lazy"></a><figcaption>01-grille-accueil.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-boutons-rapides-web/02-edition-bouton.png" target="_blank"><img src="'+r+'" alt="02-edition-bouton.png" loading="lazy"></a><figcaption>02-edition-bouton.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-boutons-rapides-web/03-ajout-bouton-page-viennoiseries.png" target="_blank"><img src="'+n+'" alt="03-ajout-bouton-page-viennoiseries.png" loading="lazy"></a><figcaption>03-ajout-bouton-page-viennoiseries.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-29-boutons-rapides-web/04-modifications-non-publiees.png" target="_blank"><img src="'+u+'" alt="04-modifications-non-publiees.png" loading="lazy"></a><figcaption>04-modifications-non-publiees.png</figcaption></figure></div>',5)])])}const h=o(d,[["render",c]]);expo